135	func buildTokensProfileReport(ctx context.Context, store *checkpoint.GitStore, infos []checkpoint.CheckpointInfo, limit int) (tokensProfileReport, error) {
136		checkpointsAvailable := len(infos)
137		infos = limitTokensProfileCheckpoints(infos, limit)
138		report := tokensProfileReport{
139			Source:               "committed_checkpoints",
140			UsageScope:           tokensProfileUsageScopeCheckpointObserved,
141			CheckpointsAvailable: checkpointsAvailable,
142			CheckpointsAnalyzed:  len(infos),
143		}
144		signals := make(map[string]*tokensProfileSignal, len(tokensProfileSignalDefinitions))
145		var aggregate *agent.TokenUsage
146	
147		for _, info := range infos {
148			if err := ctx.Err(); err != nil {
149				return tokensProfileReport{}, err //nolint:wrapcheck // Propagating context cancellation.
150			}
151	
152			summary, err := store.Read(ctx, info.CheckpointID)
153			if err != nil {
154				return tokensProfileReport{}, fmt.Errorf("failed to read checkpoint %s: %w", info.CheckpointID, err)
155			}
156			if summary == nil {
157				report.MissingTokenData++
158				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
159				continue
160			}
161	
162			usage, metadataReadWarning, err := tokensProfileCheckpointUsage(ctx, store, info.CheckpointID, summary)
163			if err != nil {
164				return tokensProfileReport{}, err
165			}
166			if metadataReadWarning {
167				report.MetadataReadWarnings++
168			}
169			tokens := buildSessionTokensUsage(usage)
170			if tokens == nil {
171				report.MissingTokenData++
172				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
173				continue
174			}
175	
176			report.CheckpointsWithTokenData++
177			aggregate = addCheckpointTokenUsage(aggregate, usage)
178			addTokensProfileTokenSignals(signals, info.CheckpointID, tokens, report.CheckpointsAnalyzed)
179		}
180	
181		report.Tokens = buildSessionTokensUsage(aggregate)
182		report.Signals = orderedTokensProfileSignals(signals)
183		report.Recommendations = tokensProfileRecommendations(report)
184		report.Limitations = tokensProfileLimitations(report)
185		return report, nil
186	}
