195	func tokensProfileCheckpointUsage(ctx context.Context, store *checkpoint.GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*agent.TokenUsage, bool, error) {
196		if summary == nil {
197			return nil, false, nil
198		}
199	
200		metas := make([]*checkpoint.Metadata, 0, len(summary.Sessions))
201		metadataReadWarning := false
202		for i := range len(summary.Sessions) {
203			meta, err := store.ReadSessionMetadata(ctx, checkpointID, i)
204			if err != nil {
205				if ctxErr := ctx.Err(); ctxErr != nil {
206					return nil, false, ctxErr //nolint:wrapcheck // Propagating context cancellation.
207				}
208				metadataReadWarning = true
209				continue
210			}
211			metas = append(metas, meta)
212		}
213		return checkpointTokenUsage(summary, metas, metadataReadWarning), metadataReadWarning, nil
214	}
