216	func addTokensProfileTokenSignals(signals map[string]*tokensProfileSignal, checkpointID id.CheckpointID, tokens *sessionTokensUsage, denominator int) {
217		if tokens == nil {
218			return
219		}
220		topLevelTotal := topLevelSessionTokenTotal(tokens)
221		if topLevelTotal > 0 && tokenPercent(tokens.CacheRead, topLevelTotal) >= recommendationHighCacheReadPercent {
222			addTokensProfileSignal(signals, "context-replay-hotspot", checkpointID, denominator)
223		}
224		if tokens.APICalls >= 20 {
225			addTokensProfileSignal(signals, "api-call-amplification", checkpointID, denominator)
226		}
227		if tokenShareAtLeastOneTenth(tokens.SubagentTotal, tokens.Total) {
228			addTokensProfileSignal(signals, "subagent-heavy", checkpointID, denominator)
229		}
230	}
