232	func addTokensProfileSignal(signals map[string]*tokensProfileSignal, signalID string, checkpointID id.CheckpointID, denominator int) {
233		signal := signals[signalID]
234		if signal == nil {
235			definition := tokensProfileSignalDefinitionFor(signalID)
236			signal = &tokensProfileSignal{
237				ID:    definition.id,
238				Label: definition.label,
239			}
240			signals[signalID] = signal
241		}
242		signal.Count++
243		if denominator > 0 {
244			signal.Percent = roundedPercent(signal.Count, denominator)
245		}
246		if checkpointID != "" {
247			signal.CheckpointIDs = append(signal.CheckpointIDs, checkpointID.String())
248		}
249	}
