251	func tokensProfileSignalDefinitionFor(signalID string) tokensProfileSignalDefinition {
252		for _, definition := range tokensProfileSignalDefinitions {
253			if definition.id == signalID {
254				return definition
255			}
256		}
257		return tokensProfileSignalDefinition{id: signalID, label: signalID}
258	}
