260	func orderedTokensProfileSignals(signals map[string]*tokensProfileSignal) []tokensProfileSignal {
261		ordered := make([]tokensProfileSignal, 0, len(signals))
262		for _, definition := range tokensProfileSignalDefinitions {
263			if signal := signals[definition.id]; signal != nil {
264				ordered = append(ordered, *signal)
265			}
266		}
267		return ordered
268	}
