270	func tokensProfileRecommendations(report tokensProfileReport) []sessionTokensRecommendation {
271		var recs []sessionTokensRecommendation
272	
273		if report.CheckpointsAnalyzed == 0 {
274			return []sessionTokensRecommendation{{
275				ID:       "no-checkpoints",
276				Severity: "low",
277				Message:  "Create checkpoints first; token profiling needs committed checkpoint metadata to identify patterns.",
278				Signals:  []string{"empty_checkpoint_history"},
279			}}
280		}
281	
282		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 ||
283			tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
284			recs = append(recs, sessionTokensRecommendation{
285				ID:       "search-before-reinvestigation",
286				Severity: "high",
287				Message:  "Use `entire search` for prior decisions/checkpoints before broad re-investigation.",
288				Signals:  []string{"cache_read_tokens", "api_call_count"},
289			})
290		}
291		if tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
292			recs = append(recs, sessionTokensRecommendation{
293				ID:       "batch-diagnostics",
294				Severity: "medium",
295				Message:  "Batch diagnostic reads around one narrowed hypothesis when API call amplification repeats.",
296				Signals:  []string{"api_call_count"},
297			})
298		}
299		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 {
300			recs = append(recs, sessionTokensRecommendation{
301				ID:       "preserve-then-compact",
302				Severity: "medium",
303				Message:  "Summarize useful findings before continuing large-context work; compact or restart only after preserving relevant context.",
304				Signals:  []string{"cache_read_tokens"},
305			})
306		}
307		if tokensProfileSignalCount(report.Signals, "subagent-heavy") > 0 {
308			recs = append(recs, sessionTokensRecommendation{
309				ID:       "scope-subagents",
310				Severity: "medium",
311				Message:  "Scope subagent tasks tightly with a narrow objective and expected output.",
312				Signals:  []string{"subagent_tokens"},
313			})
314		}
315		if report.MissingTokenData > 0 {
316			recs = append(recs, sessionTokensRecommendation{
317				ID:       "improve-token-coverage",
318				Severity: "low",
319				Message:  "Increase token coverage by using agents and checkpoints that report token usage.",
320				Signals:  []string{"missing_token_usage"},
321			})
322		}
323	
324		if len(recs) == 0 {
325			recs = append(recs, sessionTokensRecommendation{
326				ID:       "no-repeated-hotspots",
327				Severity: "low",
328				Message:  "No repeated token hotspots were visible in committed checkpoint metadata.",
329				Signals:  []string{"checkpoint_token_metadata"},
330			})
331		}
332		return recs
333	}
