344	func tokensProfileLimitations(report tokensProfileReport) []string {
345		var limitations []string
346		if report.CheckpointsAvailable > report.CheckpointsAnalyzed {
347			limitations = append(limitations, fmt.Sprintf("Limited to latest %d of %d committed checkpoints; use --limit or --all to change scope.", report.CheckpointsAnalyzed, report.CheckpointsAvailable))
348		}
349		if report.CheckpointsAnalyzed == 0 {
350			limitations = append(limitations, "No committed checkpoints found.")
351		}
352		if report.MissingTokenData > 0 {
353			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s did not include token usage.", report.MissingTokenData, tokenPluralSuffix(report.MissingTokenData)))
354		}
355		if report.MetadataReadWarnings > 0 {
356			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s had incomplete session metadata; profile used root token summaries or readable sessions where available.", report.MetadataReadWarnings, tokenPluralSuffix(report.MetadataReadWarnings)))
357		}
358		if report.Tokens != nil {
359			limitations = append(limitations, "Token totals are summed from analyzed checkpoints and may include overlapping checkpoint history; treat them as checkpoint-observed volume, not guaranteed unique session spend.")
360		}
361		if report.CheckpointsAnalyzed > 0 {
362			limitations = append(limitations, "Tool-level search/read spend is not captured yet; this profile infers patterns from token totals, cache/context replay, API call counts, and subagent totals.")
363		}
364		return limitations
365	}
